"""AI Project Builder: a reviewable blueprint, generated by explicit rules.

AATM has no executor and no model in this build, so this builder is **not** an
LLM. It is a deterministic rule engine: capability packs are selected by
keyword rules that are reported back to the caller, so every requirement and
task can be traced to the sentence that produced it.

The output is always a *proposal*. Nothing is written until ``apply_blueprint``
is called with explicit confirmation, and applying re-validates the plan first.
"""

import hashlib
import json
import re
from dataclasses import dataclass, field

from sqlalchemy import select
from sqlalchemy.orm import Session

