    keywords: tuple[str, ...]
    requirement: str
    tables: tuple[str, ...]
    tasks: tuple[tuple[str, str, str, tuple[str, ...], tuple[str, ...]], ...]
    """(task_key, title, role, depends_on, acceptance_criteria)"""
    tests: tuple[str, ...] = ()


