ARCHITECTURE_NOTES = {
    "prototype": "One deployable process, in-memory where possible, designed to be thrown away.",
    "mvp": "One API service and one web client, sharing a database and a single deploy pipeline.",
    "production": "API service, background worker, and web client as separate deployables behind a load balancer, with a managed database.",
}


def _detect_packs_safe(idea: str):
    text = idea.lower()
    selected: list[Pack] = []
    evidence: dict[str, list[str]] = {}
    for pack in PACKS:
        hits = [word for word in pack.keywords if word.lower() in text]
        if hits:
            selected.append(pack)
            evidence[pack.key] = hits
    return selected, evidence


def _slug(idea: str) -> str:
    words = re.findall(r"[A-Za-z0-9]+", idea)
    return "-".join(words[:4]).lower() or "new-project"


@dataclass
class Blueprint:
    idea: str
    scale: str
    stack: str
    data_layer: str
    team_size: int
    requirements: list[dict[str, object]] = field(default_factory=list)
    architecture: dict[str, object] = field(default_factory=dict)
    stack_plan: dict[str, object] = field(default_factory=dict)
    database: list[dict[str, object]] = field(default_factory=list)
    phases: list[dict[str, object]] = field(default_factory=list)
    tasks: list[dict[str, object]] = field(default_factory=list)
    assignments: list[dict[str, object]] = field(default_factory=list)
    dependencies: list[dict[str, str]] = field(default_factory=list)
    testing: list[str] = field(default_factory=list)
    acceptance: list[str] = field(default_factory=list)
    delivery: list[dict[str, object]] = field(default_factory=list)
    evidence: dict[str, list[str]] = field(default_factory=dict)

    def as_dict(self) -> dict[str, object]:
        payload = {
            "idea": self.idea,
            "options": {
                "scale": self.scale,
                "stack": self.stack,
                "data_layer": self.data_layer,
                "team_size": self.team_size,
            },
            "requirements": self.requirements,
            "architecture": self.architecture,
            "technology_stack": self.stack_plan,
            "database_design": self.database,
            "development_phases": self.phases,
            "task_breakdown": self.tasks,
            "assignment_plan": self.assignments,
            "dependencies": self.dependencies,
            "testing_strategy": self.testing,
            "acceptance_criteria": self.acceptance,
            "delivery_plan": self.delivery,
            "detection_evidence": self.evidence,
            "generation": {
                "generated_by": "deterministic_rules",
                "model_called": False,
                "note": (
                    "This plan comes from explicit keyword and scale rules, not from a language model. "
                    "The rules that fired are listed in detection_evidence. Review it before applying."
                ),
                "requires_review": True,
                "auto_execution": False,
            },
        }
        payload["fingerprint"] = hashlib.sha256(
            json.dumps({k: v for k, v in payload.items() if k != "fingerprint"}, sort_keys=True, ensure_ascii=False).encode()
        ).hexdigest()[:16]
        return payload


def build_blueprint(
    db: Session,
    *,
    idea: str,
    scale: str = "mvp",
    stack: str = "python-react",
    data_layer: str = "sqlite",
    team_size: int = 3,
    project_name: str | None = None,
) -> dict[str, object]:
    clean = (idea or "").strip()
    if len(clean) < 20:
        raise BlueprintError("Describe the idea in at least 20 characters so the plan has something to work from.")
    if len(clean) > MAX_IDEA:
        raise BlueprintError(f"Keep the description under {MAX_IDEA} characters.")
    if scale not in SCALES:
        raise BlueprintError(f"Scale must be one of: {', '.join(SCALES)}.")
    if stack not in STACKS:
        raise BlueprintError(f"Stack must be one of: {', '.join(STACKS)}.")
    if data_layer not in DATA_LAYERS:
        raise BlueprintError(f"Data layer must be one of: {', '.join(DATA_LAYERS)}.")
    if not 1 <= team_size <= 20:
        raise BlueprintError("Team size must be between 1 and 20 workers.")

    selected, evidence = _detect_packs_safe(clean)
    plan = Blueprint(
        idea=clean,
        scale=scale,
        stack=stack,
        data_layer=data_layer,
        team_size=team_size,
        evidence=evidence,
    )

    # 1. Requirements
    plan.requirements.append(
        {
            "id": "REQ-00",
            "text": "The product is usable locally with one documented start command and no external service required to boot.",
            "source": "scale rule",
        }
    )
    for index, pack in enumerate(selected, start=1):
        plan.requirements.append(
            {
                "id": f"REQ-{index:02d}",
                "text": pack.requirement,
                "source": f"capability pack '{pack.key}' matched keywords: {', '.join(evidence[pack.key])}",
            }
        )
    if not selected:
        plan.requirements.append(
            {
                "id": "REQ-01",
                "text": "Deliver the smallest end-to-end slice described in the idea, end to end, before adding scope.",
                "source": "no capability pack matched; default slice rule",
            }
        )

    # 2. Architecture
    plan.architecture = {
        "shape": ARCHITECTURE_NOTES[scale],
        "layers": [
            "Interface layer: views and forms with validation on both sides.",
            "Service layer: the only place business rules live.",
            "Persistence layer: migrations are the sole source of schema truth.",
        ],
        "constraints": [
            "No business rule lives in a view or a route handler.",
            "Every state change is recorded before it is reported.",
            "Secrets come from the environment or a keyring, never from source.",
        ],
        "data_layer_choice": (
            "SQLite: zero-setup, single file, ideal for this scale."
            if data_layer == "sqlite"
            else "PostgreSQL: chosen for concurrent writers; a connection URL is configuration, not code."
        ),
    }

    # 3. Technology stack
    plan.stack_plan = {
        **STACK_DETAIL[stack],
        "data": "SQLite" if data_layer == "sqlite" else "PostgreSQL",
        "why": f"Chosen by the explicit '{stack}' option, not inferred.",
    }

    # 4. Database design
    core_tables = [
        {"table": "projects", "columns": ["id", "name", "description", "created_at"], "why": "the unit of delivery"},
    ]
    for pack in selected:
        for table in pack.tables:
            core_tables.append(
                {
                    "table": table,
                    "columns": ["id", "created_at", "updated_at"],
                    "why": f"required by '{pack.key}' ({pack.requirement[:60]}…)",
                    "refine": "Add domain columns during the modelling task; this is a starting shape, not a final schema.",
                }
            )
    plan.database = core_tables

    # 5. Phases, 6. Tasks, 8. Dependencies
    task_defs: list[tuple[str, str, str, tuple[str, ...], tuple[str, ...]]] = list(BASE_TASKS)
    for pack in selected:
        task_defs.extend(pack.tasks)

    phase_of = {}
    for key, *_rest in BASE_TASKS:
        phase_of[key] = (
            "Discovery" if key == "deploy-plan" else
            "Foundation" if key in ("scaffold", "data-model") else
            "Core features" if key in ("api-skeleton", "ui-shell") else
            "Hardening"
        )
    for pack in selected:
        for task in pack.tasks:
            phase_of[task[0]] = "Core features"

    tasks = []
    for order, (key, title, role, depends_on, criteria) in enumerate(task_defs, start=1):
        tasks.append(
            {
                "key": key,
                "order": order,
                "title": title,
                "role": role,
                "phase": phase_of[key],
                "depends_on": list(depends_on),
                "acceptance_criteria": list(criteria),
                "description": f"{title}. Acceptance: {' '.join(criteria)}",
            }
        )
    plan.tasks = tasks
    plan.dependencies = [
        {"from": dependency, "to": task["key"], "type": "finish_to_start"}
        for task in tasks
        for dependency in task["depends_on"]
    ]
    plan.phases = [
        {
            "name": phase,
            "tasks": [task["key"] for task in tasks if task["phase"] == phase],
            "exit_criteria": {
                "Discovery": "Scope, requirements and risks are agreed and written down.",
                "Foundation": "The skeleton starts locally and the schema migrates up and down.",
                "Core features": "Every selected capability works end to end in the UI.",
                "Hardening": "Tests, security review and error paths are covered.",
                "Delivery": "A release can be shipped and rolled back by one named step.",
            }[phase],
        }
        for phase in PHASES
        if any(task["phase"] == phase for task in tasks)
    ]

    # 7. Assignment plan (real agents only)
    workers = list(db.scalars(select(Agent).where(Agent.is_manager.is_(False))).all())
    by_role: dict[str, list[Agent]] = {}
    for worker in workers:
        by_role.setdefault(worker.role, []).append(worker)
    assignments = []
    for task in tasks:
        candidates = [agent for agent in by_role.get(task["role"], []) if agent.status not in ("disabled", "paused")]
        chosen = sorted(candidates, key=lambda agent: agent.name)[0] if candidates else None
        assignments.append(
            {
                "task_key": task["key"],
                "role": task["role"],
                "agent_id": chosen.id if chosen else None,
                "agent_name": (chosen.is_manager and "Manager" or chosen.name) if chosen else None,
                "reason": (
                    f"Registered worker with role '{task['role']}'."
                    if chosen
                    else f"No available worker has role '{task['role']}'; register one or reassign after applying."
                ),
            }
        )
    plan.assignments = assignments

    # 9. Testing strategy
    plan.testing = [
        "Unit tests for every service rule, including the rejection paths.",
        "Integration tests for each API endpoint, asserting status codes and stored rows.",
        "An end-to-end test of the primary user journey.",
        "A migration test that applies and rolls back every revision.",
        "A security pass: input limits, authorisation on every mutating route, and no secrets in responses.",
    ] + [check for pack in selected for check in pack.tests]

    # 10. Acceptance criteria
    plan.acceptance = [
        "Each requirement above is demonstrated by a test or a recorded manual check.",
        "Every user-visible string exists in English, Arabic and Persian.",
        "Arabic and Persian render right-to-left without layout breakage.",
        "The application starts from a clean checkout with one documented command.",
        "No risky action (merge, deploy, paid call) runs without an explicit approval.",
    ] + [criteria for task in tasks for criteria in task["acceptance_criteria"]]

    # 11. Delivery plan
    plan.delivery = [
        {
            "milestone": phase["name"],
            "exit_criteria": phase["exit_criteria"],
            "task_count": len(phase["tasks"]),
            "gate": "User review before the next milestone starts.",
        }
        for phase in plan.phases
    ]
    plan.delivery.append(
        {
            "milestone": "Release",
            "exit_criteria": "All acceptance criteria pass and the rollback step is written down.",
            "task_count": 0,
            "gate": "Explicit user approval; AATM never deploys on its own.",
        }
    )

    # Summary counters make the plan scannable without inventing anything.
    payload = plan.as_dict()
    payload["summary"] = {
        "requirements": len(payload["requirements"]),
        "tasks": len(payload["task_breakdown"]),
        "phases": len(payload["development_phases"]),
        "capability_packs": [pack.key for pack in selected],
        "staffed_tasks": sum(1 for item in payload["assignment_plan"] if item["agent_id"]),
        "unstaffed_tasks": sum(1 for item in payload["assignment_plan"] if not item["agent_id"]),
        "project_name": project_name or _slug(clean).replace("-", " ").title(),
    }
    return payload


def apply_blueprint(
    db: Session,
    plan: dict[str, object],
    *,
    project_name: str | None = None,
    create_project: bool = True,
    actor: str = "local-user",
) -> dict[str, object]:
    """Materialise a reviewed plan as a project and real, dependency-linked tasks.

    Re-validates every reference first: a plan that no longer matches the
    database is rejected rather than partially applied.
    """
    tasks = plan.get("task_breakdown")
    if not isinstance(tasks, list) or not tasks:
        raise BlueprintError("This plan has no tasks to apply.")
    keys = [task.get("key") for task in tasks]
    if len(set(keys)) != len(keys):
        raise BlueprintError("The plan has duplicate task keys; regenerate it before applying.")
    known = set(keys)
    for task in tasks:
        for dependency in task.get("depends_on", []):
            if dependency not in known:
                raise BlueprintError(f"Task '{task['key']}' depends on unknown task '{dependency}'.")
            if dependency == task["key"]:
                raise BlueprintError(f"A task cannot depend on itself ('{dependency}').")

    name = (project_name or plan.get("summary", {}).get("project_name") or "New project").strip()  # type: ignore[union-attr]
    if not name:
        raise BlueprintError("A project name is required.")
    requirements = plan.get("requirements", [])
    description = (
        f"{plan.get('idea', '')}\n\n"
        + "\n".join(f"{item['id']}: {item['text']}" for item in requirements)  # type: ignore[index]
    )[:20_000]

    project: Project | None = None
    if create_project:
        project = Project(name=name[:120], description=description)
        db.add(project)
        db.flush()
        add_event(db, "project", project.id, "project.created", f"Project created from a blueprint: {project.name}")

    created: dict[str, Task] = {}
    order = {task["key"]: index for index, task in enumerate(tasks)}
    assignments = {item["task_key"]: item for item in plan.get("assignment_plan", [])}  # type: ignore[union-attr]

    for task_def in tasks:
        agent_id = assignments.get(task_def["key"], {}).get("agent_id")
        task = Task(
            project_id=project.id if project else None,
            title=str(task_def["title"])[:200],
            description=str(task_def.get("description", ""))[:20_000],
            priority="normal",
            state="assigned" if agent_id else "pending",
            assigned_agent_id=agent_id,
            acceptance_criteria=list(task_def.get("acceptance_criteria", []))[:20],
        )
        db.add(task)
        db.flush()
        created[task_def["key"]] = task

    # Wire dependencies only after every id exists.
    for task_def in tasks:
        task = created[task_def["key"]]
        task.dependencies = [created[key].id for key in task_def.get("depends_on", [])]

    ordered = [created[key] for key in sorted(created, key=lambda item: order[item])]
    add_event(
        db,
        "project",
        project.id if project else "blueprint",
        "blueprint.applied",
        f"Blueprint applied by {actor}: {len(ordered)} tasks, {len(tasks) and len(plan.get('dependencies', []))} dependencies.",
    )
    db.flush()
    return {
        "project_id": project.id if project else None,
        "project_name": project.name if project else None,
        "tasks_created": len(ordered),
        "task_ids": {key: task.id for key, task in created.items()},
        "first_task_id": ordered[0].id if ordered else None,
        "note": "Tasks were created in the pending/assigned state. Nothing was executed; the orchestrator remains the only path to running work.",
    }
